class Solution {
    fun largestPathValue(colors:String,edges:Array<IntArray>):Int{
        val n=colors.length;
        val graph=Array(n){
            mutableListOf<Int>()
        };
        val indegree=IntArray(n);
        for(edge in edges){
            graph[edge[0]].add(edge[1]);
            indegree[edge[1]]++
        };
        val dp=Array(n){
            IntArray(26)
        };
        val queue=java.util.ArrayDeque<Int>();
        for(i in 0 until n)if(indegree[i]==0){
            dp[i][colors[i]-'a']=1;
            queue.addLast(i)
        };
        var processed=0;
        var answer=0;
        while(queue.isNotEmpty()){
            val node=queue.removeFirst();
            processed++;
            answer=maxOf(answer,dp[node].maxOrNull()!!);
            for(next in graph[node]){
                val own=colors[next]-'a';
                for(color in 0 until 26)dp[next][color]=maxOf(dp[next][color],dp[node][color]+if(color==own)1 else 0);
                if(--indegree[next]==0)queue.addLast(next)
            }
        };
        return if(processed==n)answer else -1
    }
}

